  // ============ KYC FORM PROGRESS API ROUTES ============

  // Get KYC form progress for current user
  app.get("/api/kyc-progress", async (req, res) => {
    try {
      const userId = req.user?.id || "demo-user-1"; // Get from session
      const result = await db
        .select()
        .from(kycFormProgress)
        .where(eq(kycFormProgress.userId, userId))
        .limit(1);

      if (result.length === 0) {
        return res.status(404).json({ error: "No progress found" });
      }

      res.json(result[0]);
    } catch (error) {
      console.error("Error fetching KYC progress:", error);
      res.status(500).json({ error: "Failed to fetch KYC progress" });
    }
  });

  // Save/Update KYC form progress
  app.put("/api/kyc-progress", async (req, res) => {
    try {
      const userId = req.user?.id || "demo-user-1"; // Get from session
      const { 
        currentStep, 
        completedSteps, 
        completionPercentage,
        personalDetailsData,
        addressDetailsData,
        bankDetailsData,
        documentDetailsData,
        panDataSource,
        aadharDataSource,
        addressDataSource,
        autoPopulatedFields,
        isCompleted,
        completedAt
      } = req.body;

      // Check if progress exists
      const existing = await db
        .select()
        .from(kycFormProgress)
        .where(eq(kycFormProgress.userId, userId))
        .limit(1);

      let result;

      if (existing.length > 0) {
        // Update existing progress
        result = await db
          .update(kycFormProgress)
          .set({
            currentStep,
            completedSteps,
            completionPercentage,
            personalDetailsData,
            addressDetailsData,
            bankDetailsData,
            documentDetailsData,
            panDataSource,
            aadharDataSource,
            addressDataSource,
            autoPopulatedFields,
            isCompleted,
            completedAt: completedAt ? new Date(completedAt) : undefined,
            lastSavedAt: new Date(),
            updatedAt: new Date()
          })
          .where(eq(kycFormProgress.userId, userId))
          .returning();
      } else {
        // Create new progress
        result = await db
          .insert(kycFormProgress)
          .values({
            userId,
            currentStep,
            completedSteps,
            completionPercentage,
            personalDetailsData,
            addressDetailsData,
            bankDetailsData,
            documentDetailsData,
            panDataSource,
            aadharDataSource,
            addressDataSource,
            autoPopulatedFields,
            isCompleted,
            completedAt: completedAt ? new Date(completedAt) : undefined
          })
          .returning();
      }

      res.json(result[0]);
    } catch (error) {
      console.error("Error saving KYC progress:", error);
      res.status(500).json({ error: "Failed to save KYC progress" });
    }
  });

